#!/usr/bin/env python3
"""Pay Interstate Vehicle Tax - standalone Playwright version of the Teach-Once workflow."""
import argparse
import csv
import os
import re
import sys
import time

from playwright.sync_api import expect, sync_playwright

PORTAL_URL = os.environ.get("PORTAL_URL", "http://127.0.0.1:8000")

# variable name -> CSV column
VARIABLES = {
    "vehicle_registration_number": "vehicle_no",
    "owner_name": "owner_name",
    "vehicle_type": "vehicle_type",
    "from_state": "from_state",
    "to_state": "to_state",
    "entry_date": "entry_date",
    "tax_period": "tax_period",
    "mobile_number": "mobile",
}

SECRETS = {"portal_password": "PORTAL_PASSWORD"}  # name -> env var

# locators are (kind, ...) tuples, tried in order; first with exactly one visible match wins
STEPS = [
    {"id": "s01", "action": "goto", "value": "{{PORTAL_URL}}/portal/login",
     "check": ("url_contains", "/portal/login")},
    {"id": "s02", "action": "fill", "value": "operator",
     "locators": [("role", "textbox", "Username"), ("label", "Username"), ("css", "#username")],
     "check": ("value_equals",)},
    {"id": "s03", "action": "fill", "value": "{{portal_password}}",
     "locators": [("label", "Password"), ("css", "#password")]},
    {"id": "s04", "action": "click",
     "locators": [("role", "button", "Sign in"), ("css", "#login_btn")],
     "check": ("url_contains", "/portal/dashboard")},
    {"id": "s05", "action": "click",
     "locators": [("role", "link", "Pay Interstate Vehicle Tax"), ("css", "#tile_tax")],
     "check": ("url_contains", "/portal/tax/new")},
    {"id": "s06", "action": "fill", "value": "{{vehicle_registration_number}}",
     "locators": [("role", "textbox", "Vehicle registration number"),
                  ("label", "Vehicle registration number"),
                  ("placeholder", "e.g. NV07AB1234"), ("css", "#veh_no")],
     "check": ("value_equals",)},
    {"id": "s07", "action": "fill", "value": "{{owner_name}}",
     "locators": [("role", "textbox", "Owner name"), ("label", "Owner name"), ("css", "#owner_name")],
     "check": ("value_equals",)},
    {"id": "s08", "action": "select", "value": "{{vehicle_type}}",
     "locators": [("role", "combobox", "Vehicle type"), ("label", "Vehicle type"), ("css", "#vehicle_type")],
     "check": ("value_equals",)},
    {"id": "s09", "action": "select", "value": "{{from_state}}",
     "locators": [("role", "combobox", "From state"), ("label", "From state"), ("css", "#from_state")],
     "check": ("value_equals",)},
    {"id": "s10", "action": "select", "value": "{{to_state}}",
     "locators": [("role", "combobox", "To state"), ("label", "To state"), ("css", "#to_state")],
     "check": ("value_equals",)},
    {"id": "s11", "action": "fill_date", "value": "{{entry_date}}",
     "locators": [("label", "Entry date"), ("css", "#entry_date")],
     "check": ("value_equals",)},
    {"id": "s12", "action": "check",
     "locators": [("role", "radio", "{{tax_period}}"), ("label", "{{tax_period}}")]},
    {"id": "s13", "action": "fill", "value": "{{mobile_number}}",
     "locators": [("role", "textbox", "Mobile number"), ("label", "Mobile number"),
                  ("placeholder", "10-digit number"), ("css", "#mobile")],
     "check": ("value_equals",)},
    {"id": "s14", "action": "check",
     "locators": [("role", "checkbox", "I declare that the above details are correct."),
                  ("label", "I declare that the above details are correct."), ("css", "#declaration")]},
    {"id": "s15", "action": "click",
     "locators": [("role", "button", "Calculate Tax"), ("css", "#calc_btn")],
     "check": ("url_contains", "/portal/tax/review")},
    {"id": "s16", "action": "click",
     "locators": [("role", "link", "Proceed to Pay"), ("css", "#proceed_btn")],
     "check": ("url_contains", "/portal/tax/pay")},
    {"id": "s17", "action": "click",
     "locators": [("role", "button", "Pay Now (Demo)"), ("css", "#pay_btn")],
     "check": ("url_contains", "/portal/tax/receipt")},
    {"id": "s18", "action": "extract", "output": "receipt_no", "pattern": r"DTP-\d{4}-\d{6}",
     "locators": [("role", "row", "Receipt No."), ("text", "Receipt No.")]},
    {"id": "s19", "action": "extract", "output": "amount_paid", "pattern": r"D\$ [\d,]+\.\d{2}",
     "locators": [("role", "row", "Amount paid"), ("text", "Amount paid")]},
    {"id": "s20", "action": "click",
     "locators": [("role", "link", "Back to dashboard")],
     "check": ("url_contains", "/portal/dashboard")},
]


def render(template, values):
    return re.sub(r"\{\{(\w+)\}\}", lambda m: values.get(m.group(1), m.group(0)), template)


def build_locator(page, spec, values):
    kind = spec[0]
    if kind == "role":
        return page.get_by_role(spec[1], name=render(spec[2], values))
    if kind == "label":
        return page.get_by_label(render(spec[1], values))
    if kind == "placeholder":
        return page.get_by_placeholder(render(spec[1], values))
    if kind == "text":
        return page.get_by_text(render(spec[1], values))
    if kind == "css":
        return page.locator(spec[1])
    raise ValueError(f"unknown locator kind: {kind}")


def find_locator(page, step, values, timeout_s):
    deadline = time.monotonic() + timeout_s
    while True:
        for spec in step["locators"]:
            try:
                loc = build_locator(page, spec, values)
                if loc.count() == 1 and loc.first.is_visible():
                    return loc.first
            except Exception:
                continue
        if time.monotonic() >= deadline:
            raise TimeoutError(f"no locator matched exactly one visible element within {timeout_s}s")
        time.sleep(0.1)


def check_value(locator, expected, timeout_ms):
    try:
        expect(locator).to_have_value(expected, timeout=timeout_ms)
    except Exception:
        # selects: the stored value may differ from the visible label
        tag = locator.evaluate("e => e.tagName.toLowerCase()")
        if tag != "select":
            raise
        selected = locator.evaluate("e => e.options[e.selectedIndex] ? e.options[e.selectedIndex].text : ''")
        if selected != expected:
            raise AssertionError(f"expected selected {expected!r}, got {selected!r}")


def do_check(page, step, locator, value, timeout_ms):
    check = step.get("check")
    if not check:
        return
    if check[0] == "url_contains":
        expect(page).to_have_url(re.compile(re.escape(check[1])), timeout=timeout_ms)
    elif check[0] == "value_equals":
        check_value(locator, value, timeout_ms)


def run_step(page, step, values, outputs):
    timeout_s = step.get("timeout", 5)
    timeout_ms = timeout_s * 1000
    action = step["action"]
    value = render(step["value"], values) if "value" in step else None
    if action == "goto":
        page.goto(value)
        do_check(page, step, None, value, timeout_ms)
        return
    locator = find_locator(page, step, values, timeout_s)
    if action in ("fill", "fill_date"):
        locator.fill(value, timeout=timeout_ms)
    elif action == "select":
        locator.select_option(label=value, timeout=timeout_ms)
    elif action == "check":
        locator.check(timeout=timeout_ms)
    elif action == "uncheck":
        locator.uncheck(timeout=timeout_ms)
    elif action == "click":
        locator.click(timeout=timeout_ms)
    elif action == "press":
        locator.press(value, timeout=timeout_ms)
    elif action == "extract":
        text = locator.inner_text(timeout=timeout_ms)
        match = re.search(step["pattern"], text) or re.search(step["pattern"], page.content())
        if not match:
            raise ValueError(f"pattern {step['pattern']!r} not found for {step['output']}")
        outputs[step["output"]] = match.group(0)
        return
    else:
        raise ValueError(f"unknown action: {action}")
    do_check(page, step, locator, value, timeout_ms)


def row_values(row):
    values = {"PORTAL_URL": PORTAL_URL}
    for name, column in VARIABLES.items():
        values[name] = (row.get(column) or "").strip()
    for name, env in SECRETS.items():
        values[name] = os.environ.get(env, "")
    return values


def run_row(browser, row, headed_unused=None):
    values = row_values(row)
    outputs, step_id = {}, None
    context = browser.new_context(viewport={"width": 1280, "height": 800})
    try:
        page = context.new_page()
        for step in STEPS:
            step_id = step["id"]
            run_step(page, step, values, outputs)
        return outputs, None, None
    except Exception as exc:
        message = str(exc).splitlines()[0] if str(exc) else exc.__class__.__name__
        for name in SECRETS:  # never leak secrets
            if values.get(name):
                message = message.replace(values[name], "***")
        return outputs, step_id, message
    finally:
        context.close()


def main(argv=None):
    parser = argparse.ArgumentParser(description="Pay Interstate Vehicle Tax")
    parser.add_argument("csv_path", help="rows.csv")
    parser.add_argument("--limit", type=int, default=None)
    parser.add_argument("--headed", action="store_true")
    args = parser.parse_args(argv)

    with open(args.csv_path, newline="", encoding="utf-8") as fh:
        rows = list(csv.DictReader(fh))
    if args.limit is not None:
        rows = rows[: args.limit]

    with sync_playwright() as pw:
        browser = pw.chromium.launch(
            headless=not args.headed,
            executable_path=os.environ.get("CHROMIUM_PATH") or None,
        )
        try:
            for number, row in enumerate(rows, start=1):
                outputs, step_id, error = run_row(browser, row)
                if error is None:
                    print(f"row {number}: ok {outputs}")
                else:
                    print(f"row {number}: failed step {step_id}: {error}")
        finally:
            browser.close()
    return 0


if __name__ == "__main__":
    sys.exit(main())
